def _backup_path(ws):
    ws = Path(ws)
    candidates = [
        ws.parent / "system" / "openproject_drg_governance" / "state.db.pinned_backup",
        Path.cwd() / "system" / "openproject_drg_governance" / "state.db.pinned_backup",
