    raise FileNotFoundError("pinned OpenProject baseline not found")


def _rows(path, sql, params=()):
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in con.execute(sql, params)]
    finally:
        con.close()


def check_target_work_package_closed(ws):
    rows = _rows(
        _db_path(ws),
        "SELECT work_package_id, status, completed_date, cfo_evidence_attached, stakeholder_id "
        "FROM review_work_packages WHERE work_package_id = ?",
        (TARGET,),
    )
    if len(rows) != 1:
        return {"score": 0, "detail": "target work package is missing or duplicated"}
    row = rows[0]
    expected = {
        "work_package_id": TARGET,
        "status": "completed",
        "completed_date": "2025-10-24",
        "cfo_evidence_attached": 1,
        "stakeholder_id": ACTOR,
    }
    mismatches = {key: (row[key], value) for key, value in expected.items() if row[key] != value}
    return {"score": 0 if mismatches else 1, "detail": "mismatches=" + repr(mismatches) if mismatches else "target package closed correctly"}


def check_authoritative_closeout_update(ws):
    updates = _rows(
        _db_path(ws),
        "SELECT update_id, work_package_id, decision_id, stakeholder_id, update_date, update_status, "
        "evidence_ref, source_system, authoritative_flag FROM decision_action_updates "
        "WHERE work_package_id = ? AND decision_id = ? AND stakeholder_id = ? "
        "AND update_date = ? AND update_status = ? AND evidence_ref = ? "
        "AND source_system = ? AND authoritative_flag = 1",
        (TARGET, DECISION, ACTOR, "2025-10-24", "completed", EVIDENCE, "openproject"),
    )
    if not updates:
        return {"score": 0, "detail": "expected authoritative closeout update not found"}
    update_ids = {row["update_id"] for row in updates}
    events = _rows(
        _db_path(ws),
        "SELECT activity_event_id, update_id, work_package_id, decision_id, stakeholder_id, event_type "
        "FROM governance_activity_events WHERE work_package_id = ? AND decision_id = ? "
        "AND stakeholder_id = ? AND event_type = 'status_changed'",
        (TARGET, DECISION, ACTOR),
    )
    linked = [event for event in events if event["update_id"] in update_ids]
    if not linked:
        return {"score": 0, "detail": "closeout update exists without a linked status-change audit event"}
    return {"score": 1, "detail": "authoritative closeout update and linked audit event retained"}


def check_unrelated_governance_unchanged(ws):
    current = _db_path(ws)
    baseline = _backup_path(ws)
    protected_queries = [
        ("review_work_packages", "SELECT * FROM review_work_packages WHERE hospital_id = 'HRMC-001' ORDER BY work_package_id", ()),
        ("decision_action_updates", "SELECT u.* FROM decision_action_updates u JOIN review_work_packages w ON w.work_package_id = u.work_package_id WHERE w.hospital_id = 'HRMC-001' ORDER BY u.update_id", ()),
        ("governance_activity_events", "SELECT * FROM governance_activity_events WHERE decision_id IN (SELECT decision_id FROM committee_decisions WHERE hospital_id = 'HRMC-001') ORDER BY activity_event_id", ()),
    ]
    mismatches = []
    for table, sql, params in protected_queries:
        cur = _rows(current, sql, params)
        base = _rows(baseline, sql, params)
        key = {
            "review_work_packages": "work_package_id",
            "decision_action_updates": "update_id",
            "governance_activity_events": "activity_event_id",
        }[table]
        base_by_key = {row[key]: row for row in base}
        cur_by_key = {row[key]: row for row in cur}
        if table == "review_work_packages":
            comparable_cur = {k: v for k, v in cur_by_key.items() if k != TARGET}
            comparable_base = {k: v for k, v in base_by_key.items() if k != TARGET}
        else:
            new_keys = set(cur_by_key) - set(base_by_key)
            allowed_prefix = "UPD-GOV-" if table == "decision_action_updates" else "ACT-GOV-"
            allowed_new = [row for row in cur if row[key] in new_keys and row[key].startswith(allowed_prefix)]
            if len(new_keys) != 1 or len(allowed_new) != 1:
                mismatches.append(table + ":unexpected new rows")
                continue
            comparable_cur = {k: v for k, v in cur_by_key.items() if k not in new_keys}
            comparable_base = base_by_key
        if comparable_cur != comparable_base:
            mismatches.append(table)
    return {"score": 0 if mismatches else 1, "detail": "changed protected scope: " + ", ".join(mismatches) if mismatches else "unrelated governance unchanged"}

