def _database_path(workspace_path):
    workspace_root = Path(workspace_path).resolve()
    return workspace_root.parent / "system" / "hcss_heavybid_benchmarks" / "state.db"


def _result(passed, detail):
    return {"score": 1 if passed else 0, "detail": detail}


def check_controlling_version_basket_state(workspace_path):
    with sqlite3.connect(_database_path(workspace_path)) as connection:
        connection.row_factory = sqlite3.Row
        rows = connection.execute(
            """SELECT benchmark_item_id, source_version, sample_basket_flag
               FROM benchmark_bid_items
               WHERE source_document_row_key=? AND active_flag=1
               ORDER BY source_version, benchmark_item_id""",
            (TARGET_SOURCE_KEY,),
        ).fetchall()
    if len(rows) != 2:
        return _result(False, f"Expected two active versions; found {len(rows)}.")
    controlling_version = max(row["source_version"] for row in rows)
    observed = {
        row["benchmark_item_id"]: (row["source_version"], row["sample_basket_flag"])
        for row in rows
    }
    expected = {
        SUPERSEDED_ITEM_ID: (1, 0),
        CONTROLLING_ITEM_ID: (2, 1),
    }
    derived_rule_holds = all(
        row["sample_basket_flag"] == (1 if row["source_version"] == controlling_version else 0)
        for row in rows
    )
    passed = controlling_version == 2 and observed == expected and derived_rule_holds
    return _result(passed, f"Controlling version={controlling_version}; observed={observed}.")


def check_single_target_mutation_audit(workspace_path):
    with sqlite3.connect(_database_path(workspace_path)) as connection:
        connection.row_factory = sqlite3.Row
        exists = connection.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='benchmark_mutation_audit'"
        ).fetchone()
        if not exists:
            return _result(False, "The mutation audit table was not created.")
        rows = connection.execute(
            "SELECT operation_name,target_ids_json,parameters_json,changed_count FROM benchmark_mutation_audit"
        ).fetchall()
    if len(rows) != 1:
        return _result(False, f"Expected one audit entry; found {len(rows)}.")
    audit_row = rows[0]
    try:
        target_ids = json.loads(audit_row["target_ids_json"])
        parameters = json.loads(audit_row["parameters_json"])
    except (TypeError, json.JSONDecodeError) as error:
        return _result(False, f"Audit JSON could not be parsed: {error}.")
